#[cfg(test)]
mod codex_m2_final_review {
 use super::*;
 struct Fixture(PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
 fn fixture()->(Fixture,Connection){let root=std::env::temp_dir().join(format!("m2-codex-rereview-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir_all(&root).unwrap();let c=Connection::open(root.join("her-flight-deck.db")).unwrap();c.pragma_update(None,"foreign_keys","ON").unwrap();for m in crate::migrations(){c.execute_batch(m.sql).unwrap();}c.execute_batch("CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY);INSERT INTO schema_migrations VALUES(11);INSERT INTO study_materials(id,title,created_at,updated_at) VALUES('mat','Synthetic','2026-10-04','2026-10-04');").unwrap();crate::practice_sessions::save_practice_test_at(&root,"mat","Synthetic",r#"[{"question":"Synthetic","options":["A","B"],"correctIndex":0,"explanation":"","sourcePage":null}]"#,"synthetic").unwrap();(Fixture(root),c)}
 fn start(f:&Fixture,c:&Connection)->serde_json::Value {let v:String=c.query_row("SELECT id FROM practice_test_versions",[],|r|r.get(0)).unwrap();crate::practice_sessions::save_practice_session_at(&f.0,&serde_json::json!({"action":"start_or_resume","operationId":"20000000-0000-4000-8000-000000000001","materialId":"mat","versionId":v})).unwrap()}
 fn record(f:&Fixture,c:&Connection,s:&serde_json::Value){let i:String=c.query_row("SELECT id FROM practice_test_items",[],|r|r.get(0)).unwrap();crate::practice_sessions::save_practice_session_at(&f.0,&serde_json::json!({"action":"record_response","operationId":"20000000-0000-4000-8000-000000000002","attemptId":s["attemptId"],"itemId":i,"expectedRevision":0,"selectedIndex":1,"isDontKnow":false})).unwrap();}
 #[test]fn unique_index_wrong_key_refused(){let(f,c)=fixture();c.execute_batch("DROP INDEX uq_single_in_progress_attempt;CREATE UNIQUE INDEX uq_single_in_progress_attempt ON practice_attempts(id) WHERE status = 'in_progress' AND source_material_id IS NOT NULL").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"same-name UNIQUE index on id was accepted instead of material key");}
 #[test]fn no_op_ownership_trigger_refused(){let(f,c)=fixture();c.execute_batch("DROP TRIGGER trg_enforce_response_item_version_insert;CREATE TRIGGER trg_enforce_response_item_version_insert BEFORE INSERT ON practice_responses BEGIN SELECT 1;END;").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"same-name no-op ownership trigger was accepted");}
 #[test]fn receipt_wrong_frozen_version_refused(){let(f,c)=fixture();start(&f,&c);c.execute_batch("UPDATE practice_session_operations SET result_json=json_set(result_json,'$.versionId','missing-version')").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"receipt result for wrong frozen version was accepted");}
 #[test]fn in_progress_false_totals_refused(){let(f,c)=fixture();start(&f,&c);c.execute_batch("UPDATE practice_attempts SET total_questions=99,answered_count=88").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"one-question unfinished attempt with 99 total/88 answered was accepted");}
 #[test]fn startup_conversion_and_native_write_refuse_invalid_state(){let(f,c)=fixture();let s=start(&f,&c);record(&f,&c,&s);c.execute_batch("UPDATE practice_responses SET selected_index=99").unwrap();assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err());let conversion=crate::practice_sessions::run_legacy_conversion_at(&f.0);let v:String=c.query_row("SELECT id FROM practice_test_versions",[],|r|r.get(0)).unwrap();let write=crate::practice_sessions::save_practice_session_at(&f.0,&serde_json::json!({"action":"start_or_resume","operationId":"20000000-0000-4000-8000-000000000003","materialId":"mat","versionId":v}));assert!(conversion.is_err()||write.is_err(),"startup conversion and direct session write both succeed for validator-refused state");}
}
